#!/bin/sh
# An agent's program, for one case: asked anything, it asks which colour;
# asked again with the answer among what it is told, it does the work. It
# writes down which of the two each asking was.
PATH=/usr/bin:/bin
asked=$(cat)
mkdir -p "{here}/asked"
turn=$(($(ls "{here}/asked" | wc -l) + 1))
case "$asked" in
  *"Blue."*) printf 'told the answer' > "{here}/asked/$turn"; echo "Painted it blue."; echo "DECISION: done" ;;
  *) printf 'told no answer' > "{here}/asked/$turn"; echo "Which colour?"; echo "DECISION: ask" ;;
esac
